# Similarity-threshold search: cosine similarity over term vectors, threshold filter.
import math
docs = {'d1': 'archive catalog index', 'd2': 'archive of maps', 'd3': 'unrelated weather report'}
def vec(text):
    v = {}
    for t in text.lower().split():
        v[t] = v.get(t, 0) + 1
    return v
def cosine(a, b):
    dot = sum(a.get(k, 0)*v for k, v in b.items())
    na = math.sqrt(sum(v*v for v in a.values())); nb = math.sqrt(sum(v*v for v in b.values()))
    return dot/(na*nb) if na and nb else 0.0
qv = vec("archive catalog")
thr = 0.5
print("Query: archive catalog, threshold", thr)
for name, text in docs.items():
    s = cosine(qv, vec(text))
    if s >= thr:
        print(f"  {name}: {s:.3f} >= {thr}  PASS")
    else:
        print(f"  {name}: {s:.3f} < {thr}  skip")

